@page "/settings"
@using sv_621f767b2e334b1c932f9c2c098ac65d.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar">
        <ul>
            <li class="@(ActiveSection == "Profile" ? "active" : "")" @onclick='() => ActiveSection = "Profile"'>
                <span class="nav-icon">👤</span> Profile
            </li>
            <li class="@(ActiveSection == "Notifications" ? "active" : "")" @onclick='() => ActiveSection = "Notifications"'>
                <span class="nav-icon">🔔</span> Notifications
            </li>
            <li class="@(ActiveSection == "Security" ? "active" : "")" @onclick='() => ActiveSection = "Security"'>
                <span class="nav-icon">🔒</span> Security
            </li>
            <li class="@(ActiveSection == "Appearance" ? "active" : "")" @onclick='() => ActiveSection = "Appearance"'>
                <span class="nav-icon">🎨</span> Appearance
            </li>
        </ul>
    </nav>

    <main class="settings-content">
        @if (IsLoading)
        {
            <div class="loading">Loading...</div>
        }
        else
        {
            @switch (ActiveSection)
            {
                case "Profile":
                    @RenderProfileSection()
                    break;
                case "Notifications":
                    @RenderNotificationsSection()
                    break;
                case "Security":
                    @RenderSecuritySection()
                    break;
                case "Appearance":
                    @RenderAppearanceSection()
                    break;
            }
        }

        @if (!string.IsNullOrEmpty(ToastMessage))
        {
            <div class="toast @ToastType">
                @ToastMessage
            </div>
        }
    </main>
</div>

@if (ShowRevokeConfirmation)
{
    <div class="modal-overlay" @onclick="CancelRevoke">
        <div class="modal" @onclick:stopPropagation="true">
            <h3>Revoke Session</h3>
            <p>Are you sure you want to revoke this session? The device will be signed out immediately.</p>
            <div class="modal-actions">
                <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                <button class="btn btn-danger" @onclick="ConfirmRevoke">Revoke</button>
            </div>
        </div>
    </div>
}

@code {
    private string ActiveSection { get; set; } = "Profile";
    private bool IsLoading { get; set; } = true;

    // Toast
    private string? ToastMessage { get; set; }
    private string ToastType { get; set; } = "success";
    private System.Timers.Timer? _toastTimer;

    // Profile
    private string ProfileDisplayName { get; set; } = "";
    private string ProfileEmail { get; set; } = "";
    private string ProfileAvatarUrl { get; set; } = "";
    private string ProfileBio { get; set; } = "";
    private UserProfile? _savedProfile;

    // Notifications
    private bool EmailNotifications { get; set; }
    private bool PushNotifications { get; set; }
    private bool WeeklyDigest { get; set; }
    private List<ChannelItem> Channels { get; set; } = new();

    // Security
    private SecuritySettings? _securitySettings;
    private bool ChangePasswordExpanded { get; set; }
    private string CurrentPassword { get; set; } = "";
    private string NewPassword { get; set; } = "";
    private string ConfirmPassword { get; set; } = "";
    private bool TwoFactorEnabled { get; set; }
    private bool ShowRevokeConfirmation { get; set; }
    private string? _sessionToRevoke;

    // Appearance
    private string SelectedTheme { get; set; } = "Light";
    private string SelectedFontSize { get; set; } = "Medium";
    private string SelectedLanguage { get; set; } = "English";
    private bool CompactMode { get; set; }

    private static readonly string[] AvailableLanguages = { "English", "Spanish", "French", "German", "Japanese", "Chinese", "Portuguese" };

    protected override async Task OnInitializedAsync()
    {
        await LoadAllSettings();
        IsLoading = false;
    }

    private async Task LoadAllSettings()
    {
        var profile = await SettingsService.GetProfileAsync();
        _savedProfile = profile;
        ApplyProfile(profile);

        var notifs = await SettingsService.GetNotificationPrefsAsync();
        EmailNotifications = notifs.EmailNotifications;
        PushNotifications = notifs.PushNotifications;
        WeeklyDigest = notifs.WeeklyDigest;
        Channels = notifs.MutedChannels.Select(c => new ChannelItem { Name = c, IsMuted = true }).ToList();

        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        TwoFactorEnabled = _securitySettings.TwoFactorEnabled;

        var appearance = await SettingsService.GetAppearanceAsync();
        SelectedTheme = appearance.Theme;
        SelectedFontSize = appearance.FontSize;
        SelectedLanguage = appearance.Language;
        CompactMode = appearance.CompactMode;
    }

    private void ApplyProfile(UserProfile profile)
    {
        ProfileDisplayName = profile.DisplayName;
        ProfileEmail = profile.Email;
        ProfileAvatarUrl = profile.AvatarUrl;
        ProfileBio = profile.Bio;
    }

    // Profile actions
    private async Task SaveProfile()
    {
        var profile = new UserProfile(ProfileDisplayName, ProfileEmail, ProfileAvatarUrl, ProfileBio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        ShowToast("Profile saved successfully!", "success");
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile is not null)
        {
            ApplyProfile(_savedProfile);
        }
        ShowToast("Changes discarded.", "info");
    }

    // Notification actions
    private async Task SaveNotificationPrefs()
    {
        var mutedChannels = Channels.Where(c => c.IsMuted).Select(c => c.Name).ToList();
        var prefs = new NotificationPrefs(EmailNotifications, PushNotifications, WeeklyDigest, mutedChannels);
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        ShowToast("Notification preferences saved!", "success");
    }

    // Security actions
    private async Task UpdatePassword()
    {
        if (string.IsNullOrWhiteSpace(CurrentPassword) || string.IsNullOrWhiteSpace(NewPassword))
        {
            ShowToast("Please fill in all password fields.", "error");
            return;
        }
        if (NewPassword != ConfirmPassword)
        {
            ShowToast("New passwords do not match.", "error");
            return;
        }
        await SettingsService.ChangePasswordAsync(CurrentPassword, NewPassword);
        CurrentPassword = "";
        NewPassword = "";
        ConfirmPassword = "";
        ChangePasswordExpanded = false;
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        ShowToast("Password updated successfully!", "success");
    }

    private void RequestRevoke(string sessionId)
    {
        _sessionToRevoke = sessionId;
        ShowRevokeConfirmation = true;
    }

    private void CancelRevoke()
    {
        _sessionToRevoke = null;
        ShowRevokeConfirmation = false;
    }

    private async Task ConfirmRevoke()
    {
        if (_sessionToRevoke is not null)
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke);
            _securitySettings = await SettingsService.GetSecuritySettingsAsync();
            ShowToast("Session revoked.", "success");
        }
        ShowRevokeConfirmation = false;
        _sessionToRevoke = null;
    }

    // Appearance actions
    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(SelectedTheme, SelectedFontSize, SelectedLanguage, CompactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        ShowToast("Appearance settings saved!", "success");
    }

    // Toast helper
    private void ShowToast(string message, string type)
    {
        ToastMessage = message;
        ToastType = type;
        _toastTimer?.Dispose();
        _toastTimer = new System.Timers.Timer(3000);
        _toastTimer.Elapsed += (_, _) =>
        {
            ToastMessage = null;
            InvokeAsync(StateHasChanged);
            _toastTimer?.Dispose();
        };
        _toastTimer.AutoReset = false;
        _toastTimer.Start();
    }

    // Render helpers
    private RenderFragment RenderProfileSection() => __builder =>
    {
        <section class="settings-section">
            <h2>Profile</h2>

            <div class="avatar-preview">
                <img src="@ProfileAvatarUrl" alt="Avatar" class="avatar-img" />
                <span class="avatar-url">@ProfileAvatarUrl</span>
            </div>

            <div class="form-group">
                <label for="displayName">Display Name</label>
                <input id="displayName" type="text" @bind="ProfileDisplayName" class="form-control" />
            </div>

            <div class="form-group">
                <label for="email">Email</label>
                <input id="email" type="email" @bind="ProfileEmail" class="form-control" />
            </div>

            <div class="form-group">
                <label for="bio">Bio</label>
                <textarea id="bio" @bind="ProfileBio" class="form-control" rows="4"></textarea>
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
            </div>
        </section>
    };

    private RenderFragment RenderNotificationsSection() => __builder =>
    {
        <section class="settings-section">
            <h2>Notifications</h2>

            <div class="toggle-group">
                <label class="toggle-label">
                    <span>Email Notifications</span>
                    <input type="checkbox" @bind="EmailNotifications" class="toggle-switch" />
                </label>
                <label class="toggle-label">
                    <span>Push Notifications</span>
                    <input type="checkbox" @bind="PushNotifications" class="toggle-switch" />
                </label>
                <label class="toggle-label">
                    <span>Weekly Digest</span>
                    <input type="checkbox" @bind="WeeklyDigest" class="toggle-switch" />
                </label>
            </div>

            <h3>Channels</h3>
            <div class="channel-list">
                @foreach (var channel in Channels)
                {
                    <label class="channel-item">
                        <input type="checkbox" @bind="channel.IsMuted" />
                        <span>#@channel.Name</span>
                        <span class="mute-badge">@(channel.IsMuted ? "Muted" : "Active")</span>
                    </label>
                }
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveNotificationPrefs">Save Preferences</button>
            </div>
        </section>
    };

    private RenderFragment RenderSecuritySection() => __builder =>
    {
        <section class="settings-section">
            <h2>Security</h2>

            <div class="expandable-panel">
                <button class="panel-header" @onclick="() => ChangePasswordExpanded = !ChangePasswordExpanded">
                    <span>Change Password</span>
                    <span class="expand-icon">@(ChangePasswordExpanded ? "▾" : "▸")</span>
                </button>
                @if (ChangePasswordExpanded)
                {
                    <div class="panel-body">
                        <div class="form-group">
                            <label for="currentPwd">Current Password</label>
                            <input id="currentPwd" type="password" @bind="CurrentPassword" class="form-control" />
                        </div>
                        <div class="form-group">
                            <label for="newPwd">New Password</label>
                            <input id="newPwd" type="password" @bind="NewPassword" class="form-control" />
                        </div>
                        <div class="form-group">
                            <label for="confirmPwd">Confirm Password</label>
                            <input id="confirmPwd" type="password" @bind="ConfirmPassword" class="form-control" />
                        </div>
                        <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
                    </div>
                }
            </div>

            <div class="two-factor">
                <label class="toggle-label">
                    <span>Two-Factor Authentication</span>
                    <input type="checkbox" @bind="TwoFactorEnabled" class="toggle-switch" />
                </label>
                <span class="status-indicator @(TwoFactorEnabled ? "enabled" : "disabled")">
                    @(TwoFactorEnabled ? "✓ Enabled" : "✗ Disabled")
                </span>
                @if (_securitySettings?.LastPasswordChange is not null)
                {
                    <p class="meta-text">Last password change: @_securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
                }
            </div>

            <h3>Active Sessions</h3>
            <div class="sessions-table-wrapper">
                <table class="sessions-table">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th></th>
                        </tr>
                    </thead>
                    <tbody>
                        @if (_securitySettings is not null)
                        {
                            @foreach (var session in _securitySettings.Sessions)
                            {
                                <tr>
                                    <td>@session.Device</td>
                                    <td>@session.Location</td>
                                    <td>@session.LastActive.ToString("g")</td>
                                    <td>
                                        @if (session.Id != _securitySettings.Sessions.FirstOrDefault()?.Id)
                                        {
                                            <button class="btn btn-danger btn-sm" @onclick="() => RequestRevoke(session.Id)">Revoke</button>
                                        }
                                        else
                                        {
                                            <span class="current-badge">Current</span>
                                        }
                                    </td>
                                </tr>
                            }
                        }
                    </tbody>
                </table>
            </div>
        </section>
    };

    private RenderFragment RenderAppearanceSection() => __builder =>
    {
        <section class="settings-section">
            <h2>Appearance</h2>

            <div class="form-group">
                <label>Theme</label>
                <div class="radio-group">
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        <label class="radio-label">
                            <input type="radio" name="theme" value="@theme" checked="@(SelectedTheme == theme)" @onchange="() => SelectedTheme = theme" />
                            <span>@theme</span>
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <label>Font Size</label>
                <div class="radio-group">
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        <label class="radio-label">
                            <input type="radio" name="fontSize" value="@size" checked="@(SelectedFontSize == size)" @onchange="() => SelectedFontSize = size" />
                            <span>@size</span>
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <label for="language">Language</label>
                <select id="language" @bind="SelectedLanguage" class="form-control">
                    @foreach (var lang in AvailableLanguages)
                    {
                        <option value="@lang">@lang</option>
                    }
                </select>
            </div>

            <div class="toggle-group">
                <label class="toggle-label">
                    <span>Compact Mode</span>
                    <input type="checkbox" @bind="CompactMode" class="toggle-switch" />
                </label>
            </div>

            <h3>Preview</h3>
            <div class="appearance-preview @(SelectedTheme.ToLower()) @(CompactMode ? "compact" : "") font-@(SelectedFontSize.ToLower())">
                <div class="preview-header">Settings Dashboard</div>
                <p class="preview-text">This is a preview of how your content will look with the selected appearance settings.</p>
                <div class="preview-card">
                    <strong>Sample Card</strong>
                    <p>Theme: @SelectedTheme | Font: @SelectedFontSize | Language: @SelectedLanguage</p>
                </div>
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
            </div>
        </section>
    };

    public class ChannelItem
    {
        public string Name { get; set; } = "";
        public bool IsMuted { get; set; }
    }
}

